#include <cstdio>
#include <algorithm>

int main() {
    int n;
    scanf("%d", &n);
    long long best = 0, cur = 0;
    bool first = true;
    for (int i = 0; i < n; ++i) {
        long long x;
        scanf("%lld", &x);
        if (first) { cur = x; best = x; first = false; }
        else {
            cur = std::max(x, cur + x);
            best = std::max(best, cur);
        }
    }
    printf("%lld\n", best);
    return 0;
}
